components.example:
drag_area axis: :both, minimum_x: 0, maximum_x: 360, minimum_y: 0, maximum_y: 200, width: 420, height: 260 do
  card(width: 80, height: 80) { icon :move }
end

drawer opened: true, edge: :left, width: 320, modal: true do
  column(spacing: 12) { label "Navigation" }
end

drop_area keys: %w[files images], width: 420, height: 220 do
  center { label "Drop files here" }
end

drop_shadow width: 360, height: 200, blur: 0.7, horizontal_offset: 0, vertical_offset: 12, color: "#00000099" do
  card { label "Shadow source" }
end

grid columns: 3, column_spacing: 12, row_spacing: 12 do
  card { label "CPU" }
  card { label "Memory" }
  card { label "Network" }
end

grid_layout columns: 3, column_spacing: 12, row_spacing: 12 do
  card { label "CPU" }
  card { label "Memory" }
  card { label "Network" }
end

hover_area cursor: :pointing_hand, width: 320, height: 120 do
  card { label "Hover for details" }
end

rectangular_shadow width: 360, height: 200, blur: 28, spread: 2, radius: 22, offset_y: 12, color: "#00000088" do
  card { label "Elevated card" }
end

stack_layout current_index: 1, width: 520, height: 280 do
  page("Overview") { text "Overview content" }
  page("Activity") { text "Activity content" }
end

stack_view current_index: 0, animated: true, width: 520, height: 320 do
  page("Overview") { text "First page" }
  page("Details") { text "Second page" }
end

swipe_view current_index: 0, orientation: :horizontal, interactive: true do
  page("Today") { text "Today" }
  page("Tomorrow") { text "Tomorrow" }
end

rows = [{
  name: "src", kind: "folder", children: [
    { name: "app.rb", kind: "file", children: [] }
  ]
}]

tree_view rows,
  columns: [{ key: :name, label: "Name", width: 280 },
            { key: :kind, label: "Kind", width: 110 }],
  children_field: :children,
  expanded_paths: [[0]]

wrap width: 420, spacing: 8, orientation: :horizontal do
  %w[State Events Charts Media Effects].each { |name| chip name }
end
